    h, w = len(grid), len(grid[0]); out = []
    for i in range(h):
        j = 0
        while j < w:
            if grid[i][j] == color:
                k = j
                while k < w and grid[i][k] == color: k += 1
                if k - j >= min_len: out.append(('h', i, j, k - 1))
                j = k
            else: j += 1
    for j in range(w):
        i = 0
        while i < h:
            if grid[i][j] == color:
                k = i
                while k < h and grid[k][j] == color: k += 1
                if k - i >= min_len: out.append(('v', j, i, k - 1))
                i = k
            else: i += 1
    return out

def cast_ray(grid, out, i, j, di, dj, color, bg):
    """Paint color outward from (i, j) in direction (di, dj) over background cells only; mutates out."""
